/** «Помыть посуду!», «помыть  посуду», «Помыть посуду.» → один ключ */
export function goblinKey(task: string): string {
  return task.toLowerCase().replace(/ё/g, 'е').replace(/[^\p{L}\p{N}]+/gu, ' ').trim()
}

const BY_KEY = new Map(Object.entries(GOBLIN_PLANS).map(([k, v]) => [goblinKey(k), v]))

/** Готовый план, если дело совпало дословно; иначе null — план пишет модель */
export function goblinPlan(task: string): readonly string[] | null {
  return BY_KEY.get(goblinKey(task)) ?? null
}
